at::Tensor CatKernelKunlunxin(const at::ITensorListRef& tensors, int64_t dim) {
  std::vector<at::Tensor> inputs;
  bool cpu_path = false;
  for (const at::Tensor& t : tensors) {
    if (t.numel() == 0 && t.dim() == 1) {
      continue;
    }
    if (!kunlunxin::KunlunxinSupportsDtype(t.scalar_type())) {
      cpu_path = true;
    }
    inputs.push_back(t);
  }
  TORCH_CHECK(!inputs.empty(), "kunlunxin: cat expects at least one tensor");
  if (cpu_path) {
    std::vector<at::Tensor> host;
    host.reserve(inputs.size());
    for (const auto& t : inputs) {
      host.push_back(t.cpu());
    }
    return at::cat(host, dim).to(inputs[0].device());
  }

  const int64_t ndim = inputs[0].dim();
  const int64_t d = dim < 0 ? dim + ndim : dim;
  std::vector<int64_t> out_shape = inputs[0].sizes().vec();
  int64_t total = 0;
  for (const auto& t : inputs) {
    total += t.size(d);
  }
  out_shape[d] = total;

  kunlunxin::KunlunxinDeviceGuard guard(inputs[0]);
  xpytorch::xpu::api::Context* const context =
      kunlunxin::GetKunlunxinContext(inputs[0]);
  at::Tensor out = at::empty(out_shape, inputs[0].options());

  std::vector<at::Tensor> contig;
  contig.reserve(inputs.size());
  std::vector<std::unique_ptr<kunlunxin::XdnnTensorWrapper>> keep;
  keep.reserve(inputs.size());
  std::vector<xdnn_pytorch::Tensor> xdnn_inputs;
  xdnn_inputs.reserve(inputs.size());
  for (const auto& t : inputs) {
    auto contig_t = t.contiguous();
    contig.push_back(contig_t);
    keep.push_back(
        std::make_unique<kunlunxin::XdnnTensorWrapper>(contig.back()));
    xdnn_inputs.push_back(keep.back()->get());
  }
  kunlunxin::XdnnTensorWrapper t_out(out);
  KUNLUNXIN_EXEC(
      cat, xdnn_pytorch::cat(context, xdnn_inputs, d, t_out.get()));
  return out;
}

